bool StructTraits<::glic::selection::SelectedRegion::DataView, ::glic::selection::SelectedRegionPtr>::Read(
    ::glic::selection::SelectedRegion::DataView input,
    ::glic::selection::SelectedRegionPtr* output) {
  bool success = true;
  ::glic::selection::SelectedRegionPtr result(::glic::selection::SelectedRegion::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadShape(&result->shape))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::glic::selection::InteractionOptions::DataView, ::glic::selection::InteractionOptionsPtr>::Read(
    ::glic::selection::InteractionOptions::DataView input,
    ::glic::selection::InteractionOptionsPtr* output) {
  bool success = true;
  ::glic::selection::InteractionOptionsPtr result(::glic::selection::InteractionOptions::New());
  
      if (success)
        result->hide_handles = input.hide_handles();
      if (success)
        result->disable_multi_select = input.disable_multi_select();
      if (success)
        result->skip_intro_animation = input.skip_intro_animation();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::glic::selection::SuggestedAction::DataView, ::glic::selection::SuggestedActionPtr>::Read(
    ::glic::selection::SuggestedAction::DataView input,
    ::glic::selection::SuggestedActionPtr* output) {
  bool success = true;
  ::glic::selection::SuggestedActionPtr result(::glic::selection::SuggestedAction::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadIcon(&result->icon))
        success = false;
      if (success && !input.ReadAction(&result->action))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::glic::selection::RegionShape::DataView, ::glic::selection::RegionShapePtr>::Read(
    ::glic::selection::RegionShape::DataView input,
    ::glic::selection::RegionShapePtr* output) {
  using UnionType = ::glic::selection::RegionShape;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kRect: {
      ::gfx::RectF result_rect{};
      if (!input.ReadRect(&result_rect))
        return false;

      *output = UnionType::NewRect(
          std::move(result_rect));
      break;
    }
    case Tag::kPolyline: {
      std::vector<::gfx::PointF> result_polyline{};
      if (!input.ReadPolyline(&result_polyline))
        return false;

      *output = UnionType::NewPolyline(
          std::move(result_polyline));
      break;
    }
    default:

      return false;
  }
  return true;
}

